// Generated from the typed product locale registry by scripts/study-report/document-language.mjs.
// W10 report copy is English; host/browser locale never selects its document language.
// This serialized artifact is checked byte-for-byte against that registry before packaging.
export const REPORT_DOCUMENT_LANGUAGE = Object.freeze(JSON.parse('{"canonicalLocale":"en-US","direction":"ltr"}'));
